WITH ring AS (SELECT user_id FROM UNNEST(['0eef7feb-6940-4b7a-8cd9-f75a89d39748','4ccf6756-24dd-447d-be55-00b355a0579c','cd64db52-8aa1-460f-844c-8f3446c69e06','d2ace606-f4d3-4744-a045-5dcbcfbe4edd','accf9b2d-f2f1-4bd2-aa63-9e504a6da1c1','da29bb06-a46b-4b4b-a1c6-f68e0bf48b93','5d67575e-2c74-4aad-85f2-6a5b7b99d327','64eb8bad-7fe9-4d9d-a6b6-fbddf1a5f1e4']) user_id),
issued AS (SELECT user_id, DATE(MIN(date),'Asia/Manila') issued_on FROM `epicac-2.epicac_prod_direct.public_account_status_transitions` WHERE new_state='ApprovedAndIssued' GROUP BY 1 HAVING issued_on > '2026-05-05'),
st AS (SELECT * FROM (SELECT id, user_id, to_date, due_date, SAFE_CAST(ending_balance AS NUMERIC) bal, SAFE_CAST(minimum_payment_due AS NUMERIC) min_due, SAFE_CAST(total_charges_net_installments AS NUMERIC) charges, SAFE_CAST(total_payments AS NUMERIC) payments, datastream_metadata.change_type ct FROM `epicac-2.epicac_prod_direct.public_statements` QUALIFY ROW_NUMBER() OVER (PARTITION BY id ORDER BY datastream_metadata.source_timestamp DESC)=1) WHERE ct!='DELETE'),
first_st AS (SELECT user_id, to_date, due_date, bal, min_due, charges FROM st QUALIFY ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY to_date)=1),
dqh AS (SELECT user_id, MIN(DATE_SUB(effective_delinquency_date, INTERVAL days_past_due-16 DAY)) went_bad_on, MAX(days_past_due) max_dpd FROM `epicac-2.epicac_prod_direct.public_delinquent_accounts` WHERE days_past_due>15 GROUP BY 1),
dqn AS (SELECT user_id, days_past_due dpd_now, SAFE_CAST(delinquent_balance AS NUMERIC) dq_bal FROM `epicac-2.epicac_prod_direct.public_delinquent_accounts` QUALIFY ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY datastream_metadata.source_timestamp DESC)=1),
fpd AS (SELECT i.user_id, i.issued_on, f.to_date first_close, f.due_date first_due, f.bal first_bal, f.charges first_charges, d.went_bad_on, d.max_dpd FROM issued i JOIN first_st f USING (user_id) JOIN dqh d USING (user_id)
  WHERE f.due_date <= '2026-10-12' AND f.bal>0 AND ABS(DATE_DIFF(d.went_bad_on, DATE_ADD(f.due_date, INTERVAL 16 DAY), DAY)) <= 1),
lim AS (SELECT user_id, MAX(SAFE_CAST(credit_limit AS INT64)) credit_limit FROM `epicac-2.epicac_prod_direct.public_cards` GROUP BY 1),
pay AS (SELECT user_id, COUNTIF(status='Success') n_pay, SUM(IF(status='Success',SAFE_CAST(amount AS NUMERIC),0)) paid FROM (SELECT * FROM `epicac-2.epicac_prod_direct.public_incoming_payments` QUALIFY ROW_NUMBER() OVER (PARTITION BY id ORDER BY datastream_metadata.source_timestamp DESC)=1) GROUP BY 1),
stpay AS (SELECT user_id, SUM(payments) stmt_payments FROM st GROUP BY 1),
ph AS (SELECT user_id, COUNT(DISTINCT phone) n_phones FROM `epicac-2.epicac_prod_direct.public_user_phone_numbers` GROUP BY 1),
p AS (SELECT user_id, LOWER(REGEXP_REPLACE(JSON_VALUE(onboarding_data,'$.personal.first_name'), r'[^A-Za-z ]','')) fn, JSON_VALUE(onboarding_data,'$.work.status.type') emp_type FROM `epicac-2.epicac_prod_direct.public_user_personals` QUALIFY ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY datastream_metadata.source_timestamp DESC)=1),
ac AS (SELECT a.user_id, LOWER(REGEXP_REPLACE(JSON_VALUE(a.metadata,'$.first_name'), r'[^A-Za-z ]','')) inv_fn, g.access_code_id IS NOT NULL golden FROM `epicac-2.epicac_prod_direct.public_access_codes` a LEFT JOIN `epicac-2.epicac_prod_direct.public_golden_tickets` g ON g.access_code_id=a.id WHERE a.user_id IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY a.user_id ORDER BY a.redeemed_at DESC)=1),
pdf AS (SELECT DISTINCT user_id, JSON_VALUE(data,'$.account_number') acct FROM `epicac-2.epicac_prod_direct.public_pdf_bank_statements` WHERE LENGTH(JSON_VALUE(data,'$.account_number'))>=6),
shared AS (SELECT a.user_id, COUNT(DISTINCT b.user_id) n_shared FROM pdf a JOIN pdf b ON a.acct=b.acct AND a.user_id!=b.user_id GROUP BY 1),
keys AS (SELECT DISTINCT user_id, 'device' kt, device_id k FROM `epicac-2.epicac_prod_direct.public_device_events` WHERE device_id IS NOT NULL
  UNION ALL SELECT DISTINCT user_id, 'ip', CASE WHEN STRPOS(SPLIT(ip_address,',')[OFFSET(0)],':')>0 THEN ARRAY_TO_STRING(ARRAY(SELECT x FROM UNNEST(SPLIT(SPLIT(ip_address,',')[OFFSET(0)],':')) x WITH OFFSET o WHERE o<4 ORDER BY o),':') ELSE SPLIT(ip_address,',')[OFFSET(0)] END FROM `epicac-2.epicac_prod_direct.public_device_events` WHERE ip_address IS NOT NULL),
kc AS (SELECT kt,k, COUNT(DISTINCT user_id) n FROM keys GROUP BY 1,2 HAVING n BETWEEN 2 AND 6),
bad AS (SELECT user_id FROM dqh WHERE max_dpd>30 UNION DISTINCT SELECT user_id FROM `epicac-2.epicac_prod_direct.public_account_standing_changelog` WHERE new_account_standing LIKE '%uspend%'),
badlink AS (SELECT a.user_id, COUNT(DISTINCT b.user_id) n_badlinks FROM keys a JOIN kc USING (kt,k) JOIN keys b ON b.kt=a.kt AND b.k=a.k AND b.user_id!=a.user_id JOIN bad ON bad.user_id=b.user_id WHERE a.user_id IN (SELECT user_id FROM fpd) GROUP BY 1)
SELECT f.user_id, f.issued_on, f.first_close, f.first_due, f.went_bad_on, f.max_dpd, n.dpd_now, n.dq_bal, l.credit_limit, f.first_charges, ROUND(SAFE_DIVIDE(f.first_charges, l.credit_limit),2) first_util,
  COALESCE(pa.n_pay,0) n_pay, COALESCE(pa.paid,0)+COALESCE(sp.stmt_payments,0) paid_total, COALESCE(ph.n_phones,1) n_phones, p.emp_type,
  CASE WHEN ac.user_id IS NULL OR ac.golden OR ac.inv_fn IS NULL OR ac.inv_fn='' THEN 'none' WHEN ac.inv_fn=p.fn OR STRPOS(p.fn,ac.inv_fn)>0 OR STRPOS(ac.inv_fn,p.fn)>0 THEN 'match' ELSE 'mismatch' END invite_cls,
  COALESCE(s.n_shared,0) n_shared_acct, COALESCE(bl.n_badlinks,0) n_badlinks, f.user_id IN (SELECT user_id FROM ring) is_ring
FROM fpd f LEFT JOIN lim l USING (user_id) LEFT JOIN pay pa USING (user_id) LEFT JOIN stpay sp USING (user_id) LEFT JOIN ph USING (user_id) LEFT JOIN p USING (user_id) LEFT JOIN ac USING (user_id) LEFT JOIN shared s USING (user_id) LEFT JOIN badlink bl USING (user_id) LEFT JOIN dqn n USING (user_id)
ORDER BY f.issued_on
